package com.littlemorning.alarm;
import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.*;
import android.view.*;
import android.view.accessibility.*;
import android.widget.*;
import java.io.*;
import java.util.*;

/** Runs only on a disposable emulator: resets the target app's demo preferences. */
public final class RedesignInstrumentation extends Instrumentation {
    private Context target;private MainActivity home;private Activity playerWindow;private File screenshots;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    private void main(Runnable action){final Throwable[] error={null};runOnMainSync(()->{try{action.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new AssertionError(error[0]);}
    private View find(View root,String text){if(root instanceof TextView&&text.equals(((TextView)root).getText().toString()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),text);if(found!=null)return found;}return null;}
    private View view(Activity activity,String text){final View[] out={null};main(()->out[0]=find(activity.getWindow().getDecorView(),text));if(out[0]==null)throw new AssertionError("Missing UI: "+text);return out[0];}
    private void click(Activity activity,String text){View v=view(activity,text);main(()->{View at=v;while(!at.isClickable()&&at.getParent() instanceof View)at=(View)at.getParent();if(!at.performClick())throw new AssertionError("Not clickable: "+text);});waitForIdleSync();SystemClock.sleep(300);}
    private void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(600);Activity shown=playerWindow!=null&&!playerWindow.isFinishing()?playerWindow:home;for(int attempt=0;attempt<4;attempt++){final int[] size=new int[2];main(()->{size[0]=shown.getWindow().getDecorView().getWidth();size[1]=shown.getWindow().getDecorView().getHeight();});if(size[0]==0||size[1]==0){SystemClock.sleep(300);continue;}Bitmap b=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);final int[] result={-1};main(()->PixelCopy.request(shown.getWindow(),b,value->{result[0]=value;latch.countDown();},new Handler(Looper.getMainLooper())));if(!latch.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("Window screenshot timed out");if(result[0]!=PixelCopy.SUCCESS){b.recycle();SystemClock.sleep(400);continue;}try(FileOutputStream out=new FileOutputStream(new File(screenshots,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();return;}throw new AssertionError("No rendered window for "+name);}
    private void dump(View v,PrintWriter out,int depth){int[] xy=new int[2];main(()->v.getLocationOnScreen(xy));out.println(depth+" "+v.getClass().getSimpleName()+" "+xy[0]+","+xy[1]+" "+v.getWidth()+"x"+v.getHeight()+" "+(v instanceof TextView?((TextView)v).getText():""));if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)dump(((ViewGroup)v).getChildAt(i),out,depth+1);}
    private View description(View v,String prefix){if(v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith(prefix))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=description(((ViewGroup)v).getChildAt(i),prefix);if(found!=null)return found;}return null;}
    private int[] center(View v){final int[] xy=new int[2];main(()->{v.getLocationOnScreen(xy);xy[0]+=v.getWidth()/2;xy[1]+=v.getHeight()/2;});return xy;}
    private void inject(int action,long down,int x,int y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);boolean accepted=getUiAutomation().injectInputEvent(event,true);event.recycle();if(!accepted)throw new AssertionError("Touch injection rejected "+action);}
    private void resetTouch(){MotionEvent event=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),MotionEvent.ACTION_CANCEL,0,0,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();}
    private void reorder() throws Exception {
        final View[] handle={null};main(()->handle[0]=description(home.getWindow().getDecorView(),"排序天气示例"));if(handle[0]==null)throw new AssertionError("Missing drag handle");int[] from=center(handle[0]),to=center(view(home,"晨间旋律"));long down=SystemClock.uptimeMillis();
        try{inject(MotionEvent.ACTION_DOWN,down,from[0],from[1]);SystemClock.sleep(800);for(int i=1;i<=8;i++){inject(MotionEvent.ACTION_MOVE,down,from[0]+(to[0]-from[0])*i/8,from[1]+(to[1]-from[1])*i/8);SystemClock.sleep(80);}inject(MotionEvent.ACTION_UP,down,to[0],to[1]);}finally{resetTouch();}
        long end=SystemClock.elapsedRealtime()+4000;while(SystemClock.elapsedRealtime()<end&&!Config.prefs(target).getString("order","").startsWith("weather,music"))SystemClock.sleep(100);if(!Config.prefs(target).getString("order","").startsWith("weather,music"))throw new AssertionError("Drag order did not persist: "+Config.prefs(target).getString("order",""));shot("04b-drag-order");
        main(()->{View v=description(home.getWindow().getDecorView(),"排序天气示例");v.performClick();});waitForIdleSync();AccessibilityNodeInfo popup=getUiAutomation().getRootInActiveWindow();java.util.List<AccessibilityNodeInfo> nodes=popup.findAccessibilityNodeInfosByText("下移");if(nodes.isEmpty())throw new AssertionError("No accessible reorder alternative");AccessibilityNodeInfo action=nodes.get(0);while(!action.isClickable()&&action.getParent()!=null)action=action.getParent();if(!action.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Reorder accessibility action rejected");end=SystemClock.elapsedRealtime()+4000;while(SystemClock.elapsedRealtime()<end&&!Config.prefs(target).getString("order","").startsWith("music,weather"))SystemClock.sleep(100);if(!Config.prefs(target).getString("order","").startsWith("music,weather"))throw new AssertionError("Accessible reorder did not persist");
    }
    private void fontScale(float scale)throws Exception{ActivityMonitor m=addMonitor(MainActivity.class.getName(),null,false);try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("settings put system font_scale "+scale);FileInputStream in=new FileInputStream(fd.getFileDescriptor())){while(in.read()!=-1){}}Activity a=waitForMonitorWithTimeout(m,20000);removeMonitor(m);if(!(a instanceof MainActivity))throw new AssertionError("Font size recreation failed");home=(MainActivity)a;waitForIdleSync();if(Math.abs(home.getResources().getConfiguration().fontScale-scale)>.05)throw new AssertionError("Font scale did not apply");}
    private void waitPhase(String wanted,int seconds){long end=SystemClock.elapsedRealtime()+seconds*1000L;while(SystemClock.elapsedRealtime()<end){if(Config.prefs(target).getString("phase","").equals(wanted))return;SystemClock.sleep(150);}throw new AssertionError("Wanted "+wanted+", got "+Config.prefs(target).getString("phase","")+": "+Config.prefs(target).getString("detail",""));}
    private void state(String order,boolean weather,boolean music,boolean agenda,boolean reminders){Config.prefs(target).edit().putString("order",order).putBoolean("weather",weather).putBoolean("music",music).putBoolean("agenda",agenda).putBoolean("reminders",reminders).apply();}
    @Override public void onStart(){Bundle report=new Bundle();try{
        target=getTargetContext();resetTouch();screenshots=new File(target.getExternalFilesDir(null),"redesign-previews");screenshots.mkdirs();for(File old:screenshots.listFiles())if(old.getName().endsWith(".png")||old.getName().equals("layout.txt"))old.delete();Config.prefs(target).edit().clear().commit();
        home=(MainActivity)startActivitySync(new Intent(target,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();view(home,"明天，几点醒来？");shot("01-setup-time");
        click(home,"下一步");view(home,"想怎样开始今天？");shot("02-presets");click(home,"轻柔唤醒");click(home,"用这个方案开始");view(home,"下一次起床");view(home,"试听我的早晨");shot("03-home-day");try(PrintWriter out=new PrintWriter(new File(screenshots,"layout.txt"))){dump(home.getWindow().getDecorView(),out,0);}
        click(home,"编辑  ›");view(home,"长按把手排序，点内容进入设置。");shot("04-order");reorder();
        click(home,"天气示例");view(home,"选择所在城市");click(home,"保存城市");
        click(home,"完成");fontScale(1.3f);shot("03b-home-large-font");View primary=view(home,"试听我的早晨");int[] btn=center(primary);if(primary.getHeight()<Ui.dp(target,56)||btn[0]-primary.getWidth()/2<Ui.dp(target,23))throw new AssertionError("Primary action clipped at large font");fontScale(1f);click(home,"设置");view(home,"设置你的偏好");shot("05-settings");
        ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);Config.prefs(target).edit().putString("theme","night").commit();main(()->home.recreate());Activity next=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);if(!(next instanceof MainActivity))throw new AssertionError("Night recreation failed");home=(MainActivity)next;waitForIdleSync();if(home.getColor(R.color.bg)!=Color.rgb(18,24,21))throw new AssertionError("Night palette mismatch");
        main(()->home.onBackPressed());waitForIdleSync();shot("06-home-night");
        state("music,weather,agenda,reminders",false,true,true,false);Config.prefs(target).edit().putString("agendaSource","calendar").commit();
        ActivityMonitor alarmMonitor=addMonitor(AlarmActivity.class.getName(),null,false);main(()->Config.schedule(target,System.currentTimeMillis()+10000,false));waitPhase("ringing",45);Activity ring=waitForMonitorWithTimeout(alarmMonitor,20000);removeMonitor(alarmMonitor);if(!(ring instanceof AlarmActivity))throw new AssertionError("Alarm page did not open");playerWindow=ring;waitForIdleSync();View wake=view(ring,"长按，我起床了");final int[] xy=new int[2];main(()->{wake.getLocationOnScreen(xy);xy[0]+=wake.getWidth()/2;xy[1]+=wake.getHeight()/2;if(wake.getHeight()<Ui.dp(target,80))throw new AssertionError("Wake target too small");});
        long down=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,xy[0],xy[1],0));SystemClock.sleep(150);sendPointerSync(MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,xy[0],xy[1],0));SystemClock.sleep(300);if(!Config.prefs(target).getString("phase","").equals("ringing"))throw new AssertionError("Short tap dismissed alarm");shot("07-ringing-night");
        down=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,xy[0],xy[1],0));SystemClock.sleep(1100);sendPointerSync(MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,xy[0],xy[1],0));waitPhase("speaking",15);SystemClock.sleep(1000);shot("08-player-night");click(ring,"暂停");waitPhase("paused",10);shot("09-paused-night");click(ring,"继续");waitPhase("speaking",10);click(ring,"下一条");waitPhase("done",15);if(!Config.prefs(target).getString("skipNotes","").contains("日历未授权"))throw new AssertionError("Calendar denial was not skipped");shot("10-complete-skipped");click(ring,"开始我的一天");
        state("reminders,music,weather,agenda",false,false,false,true);Config.prefs(target).edit().putString("reminderText","").commit();main(()->Config.start(target,Config.SPEAK));waitPhase("done",10);if(!Config.prefs(target).getString("skipNotes","").contains("提醒为空"))throw new AssertionError("Empty reminder not skipped");SystemClock.sleep(500);if(AlarmService.active)throw new AssertionError("Service leaked on completion");
        state("weather,music,agenda,reminders",true,false,false,false);main(()->Config.start(target,Config.SPEAK));waitPhase("done",60);report.putString("speechOutcome",Config.prefs(target).getString("skipNotes","No skipped voice parts"));
        Config.preset(target,"soft");Config.prefs(target).edit().putString("theme","system").commit();
        report.putString("stream","PASS: 2-step setup, preset selection, home/routine/detail/settings navigation, drag and accessible reorder, 130% font recreation, night recreation, 10-second exact alarm, short-tap prevention, hold-to-broadcast, local music, pause/resume/skip, denied-calendar continuation, empty-content skip, missing-voice or TTS completion, service cleanup. Screenshots: "+screenshots+"\n");finish(Activity.RESULT_OK,report);
    }catch(Throwable t){StringWriter trace=new StringWriter();t.printStackTrace(new PrintWriter(trace));report.putString("stream","FAIL: "+trace+"\n");finish(Activity.RESULT_CANCELED,report);}}
}
